import { createAes256GcmTransformer } from '@forepath/shared/backend';
import { Column, CreateDateColumn, Entity, PrimaryGeneratedColumn } from 'typeorm';

/**
 * A DNSSEC signing key of a bind9-hosted zone (3.15): generated by the control plane so every bind9 instance signs
 * with the same key. The private key is stored encrypted and reaches the name servers at push time only.
 */
@Entity('lw_dnssec_keys')
export class DnssecKeyEntity {
  @PrimaryGeneratedColumn('uuid', { name: 'id' })
  id!: string;

  /** `DnsZone` resource name. */
  @Column({ type: 'varchar', length: 63, name: 'zone' })
  zone!: string;

  @Column({ type: 'integer', name: 'key_tag' })
  keyTag!: number;

  /** DNSKEY public key (base64). */
  @Column({ type: 'text', name: 'public_key' })
  publicKey!: string;

  @Column({ type: 'text', name: 'private_key', transformer: createAes256GcmTransformer() })
  privateKey!: string;

  @CreateDateColumn({ name: 'created_at', type: 'timestamptz' })
  createdAt!: Date;

  /** Set when a successor took over. */
  @Column({ type: 'timestamptz', name: 'retired_at', nullable: true })
  retiredAt!: Date | null;

  @Column({ type: 'boolean', name: 'ds_at_parent', default: false })
  dsAtParent!: boolean;

  @Column({ type: 'timestamptz', name: 'ds_absent_since', nullable: true })
  dsAbsentSince!: Date | null;

  @Column({ type: 'timestamptz', name: 'ds_present_since', nullable: true })
  dsPresentSince!: Date | null;

  @Column({ type: 'timestamptz', name: 'ds_checked_at', nullable: true })
  dsCheckedAt!: Date | null;
}
